<template><div class="page"><div class="container checkout"><section><div class="eyebrow">02 — PAYMENT</div><h1 class="h2">Choose payment.</h1><div class="methods"><label v-for="m in methods" :key="m.id" class="method" :class="{selected:method===m.id}"><input type="radio" v-model="method" :value="m.id"/><div><b>{{m.name}}</b><p>{{m.desc}}</p></div></label></div><button class="btn" @click="next">Continue to review</button></section><OrderSummary/></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import OrderSummary from './OrderSummary.vue';const router=useRouter();const method=ref('card');const methods=[{id:'card',name:'Card',desc:'Pay securely by card.'},{id:'cod',name:'Cash on delivery',desc:'Pay when your order arrives.'}];function next(){sessionStorage.setItem('vora_payment',method.value);router.push('/checkout/review')}</script>
<style scoped>.checkout{display:grid;grid-template-columns:1fr 360px;gap:50px;max-width:1050px}.methods{display:grid;gap:12px;margin:30px 0}.method{border:1px solid #ddd;border-radius:13px;padding:18px;display:flex;gap:13px}.method.selected{border-color:#111;box-shadow:0 0 0 1px #111}.method p{margin:5px 0 0;color:#777}@media(max-width:800px){.checkout{grid-template-columns:1fr}}</style>
